import {
  CONSTANTS,
  asn_dashboard_setting,
  tasks_notification_setting,
  supplier_dashboard_setting,
  workflow_builder_setting,
  report_setting,
  analytics_dashboard_setting,
  invoice_dashboard_setting,
  doc_operator_setting,
  docnet_setting,
  open_search_enabled,
} from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';

export interface ModuleRoute {
  settingKey: string;
  pathPrefixes: string[];
}

export function isModuleRouteActive(
  path: string | undefined,
  userSettings: Record<string, unknown>,
): boolean {
  if (!path) return true;
  if (!settingsLoaded(userSettings)) return true;

  const gatingModule = findGatingModule(path);
  if (!gatingModule) return true;

  // Module flags may be stored as "1"/"0" (backend/script writes) or
  // "true"/"false"; toBoolPreference normalises both so a stored "0" doesn't
  // read as truthy and "1" doesn't fail a strict comparison.
  return toBoolPreference(userSettings[gatingModule.settingKey]);
}

export function filterActiveEntries<T extends { path?: string }>(
  entries: T[],
  userSettings: Record<string, unknown>,
): T[] {
  return entries.filter((entry) =>
    isModuleRouteActive(entry.path, userSettings),
  );
}

function findGatingModule(path: string): ModuleRoute | undefined {
  const route = stripQuery(path);
  return GATED_MODULES.find((gatingModule) => ownsRoute(gatingModule, route));
}

function ownsRoute(gatingModule: ModuleRoute, route: string): boolean {
  return gatingModule.pathPrefixes.some(
    (prefix) => route === prefix || route.startsWith(prefix + '/'),
  );
}

function stripQuery(path: string): string {
  const queryStart = path.indexOf('?');
  return queryStart === -1 ? path : path.slice(0, queryStart);
}

function settingsLoaded(userSettings: Record<string, unknown>): boolean {
  return Object.keys(userSettings).length > 0;
}

const GATED_MODULES: ModuleRoute[] = [
  {
    settingKey: asn_dashboard_setting,
    pathPrefixes: ['/asn_shipment/dashboard'],
  },
  { settingKey: tasks_notification_setting, pathPrefixes: ['/tasks'] },
  {
    settingKey: supplier_dashboard_setting,
    pathPrefixes: ['/supplier/dashboard'],
  },
  {
    settingKey: workflow_builder_setting,
    pathPrefixes: ['/workflowsdashboard'],
  },
  {
    settingKey: CONSTANTS.po_dashboard,
    pathPrefixes: ['/purchase-order', '/purchase-order-detail'],
  },
  { settingKey: report_setting, pathPrefixes: ['/report'] },
  {
    settingKey: analytics_dashboard_setting,
    pathPrefixes: ['/analytics-dashboard'],
  },
  {
    settingKey: invoice_dashboard_setting,
    pathPrefixes: ['/invoice/dashboard'],
  },
  {
    settingKey: CONSTANTS.shipment_order_dashboard,
    pathPrefixes: ['/shipment-order'],
  },
  { settingKey: doc_operator_setting, pathPrefixes: ['/doc-operator'] },
  { settingKey: docnet_setting, pathPrefixes: ['/doc-net'] },
  {
    settingKey: CONSTANTS.supplier_statistics_setting,
    pathPrefixes: ['/supplier-statistic'],
  },
  {
    settingKey: open_search_enabled,
    pathPrefixes: ['/full-search', '/graph-explorer'],
  },
  {
    // The Touchless report itself is a tab on /analytics-dashboard (gated
    // there by the same flag), so what this prefix guards are the two
    // shareable drill-down links: /touchless-intelligence/supplier/:id and
    // /touchless-intelligence/document/:id/trace. Same module switch as the
    // dashboard they drill into — Touchless has no flag of its own.
    settingKey: analytics_dashboard_setting,
    pathPrefixes: ['/touchless-intelligence'],
  },
];
